text:
Here's your water tracker with a goal of 8 glasses. Tap **+ Glass** after each one, and **Undo** if you tap by mistake. The count starts fresh each day.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  body { font-family: Segoe UI, sans-serif; text-align: center; padding: 24px; margin: 0; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  #date { color: #666; font-size: 14px; margin-bottom: 20px; }
  #glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; max-width: 320px; margin: 0 auto 20px; }
  .g { width: 56px; height: 72px; border: 3px solid #2b7bd6; border-radius: 6px 6px 14px 14px; background: #fff; }
  .g.full { background: #5fb0f5; }
  #count { font-size: 32px; font-weight: 600; margin-bottom: 4px; }
  #msg { height: 22px; color: #2b7bd6; margin-bottom: 16px; }
  button { font-size: 16px; padding: 10px 20px; margin: 0 6px; border-radius: 8px; border: 1px solid #2b7bd6; cursor: pointer; }
  #add { background: #2b7bd6; color: #fff; }
  #undo, #reset { background: #fff; color: #2b7bd6; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="glasses"></div>
  <div id="count"></div>
  <div id="msg"></div>
  <button id="add">+ Glass</button>
  <button id="undo">Undo</button>
  <button id="reset">Reset</button>
<script>
  var GOAL = 8;
  var today = new Date();
  var key = "water-" + today.toISOString().slice(0, 10);
  var n = 0;
  try { n = parseInt(localStorage.getItem(key) || "0", 10) || 0; } catch (e) {}
  document.getElementById("date").textContent = today.toDateString();

  function save() { try { localStorage.setItem(key, String(n)); } catch (e) {} }

  function draw() {
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var d = document.createElement("div");
      d.className = "g" + (i < n ? " full" : "");
      box.appendChild(d);
    }
    document.getElementById("count").textContent = n + " / " + GOAL + " glasses";
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Well done!" : (GOAL - n) + " more to go";
  }

  document.getElementById("add").onclick = function () { n++; save(); draw(); };
  document.getElementById("undo").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```
